#include <gtest/gtest.h>

#include <cmath>

#include "ros2lab_hardware/protocol.hpp"

namespace pb = ros2lab_bridge;

static std::vector<pb::Frame> parse_all(const std::vector<uint8_t> & bytes, pb::Parser & p)
{
  std::vector<pb::Frame> out;
  pb::Frame f;
  for (uint8_t b : bytes) {if (p.push(b, f)) {out.push_back(f);}}
  return out;
}

TEST(Protocol, CrcKnownValue)
{
  const char * s = "123456789";   // CRC-16/CCITT-FALSE check value
  EXPECT_EQ(pb::crc16(reinterpret_cast<const uint8_t *>(s), 9), 0x29B1);
}

TEST(Protocol, CommandRoundTrip)
{
  pb::Parser p;
  const std::vector<float> v{0.5F, -1.25F, 3.0F};
  const auto frames = parse_all(pb::make_command(v), p);
  ASSERT_EQ(frames.size(), 1u);
  std::vector<float> back;
  ASSERT_TRUE(pb::parse_command(frames[0], back));
  EXPECT_EQ(back, v);
}

TEST(Protocol, StateWithImuRoundTrip)
{
  pb::State s;
  s.ms = 123456;
  s.position = {0.1F, 0.2F};
  s.velocity = {1.5F, -2.0F};
  s.has_imu = true;
  s.imu.q = {0.F, 0.F, 0.7071F, 0.7071F};
  s.imu.gyro = {0.01F, 0.02F, 0.03F};
  s.imu.accel = {0.F, 0.F, 9.81F};
  pb::Parser p;
  const auto frames = parse_all(pb::make_state(s), p);
  ASSERT_EQ(frames.size(), 1u);
  pb::State r;
  ASSERT_TRUE(pb::parse_state(frames[0], r));
  EXPECT_EQ(r.ms, 123456u);
  EXPECT_EQ(r.position, s.position);
  EXPECT_EQ(r.velocity, s.velocity);
  EXPECT_TRUE(r.has_imu);
  EXPECT_FLOAT_EQ(r.imu.accel[2], 9.81F);
}

TEST(Protocol, MaxJointsWithImuFits)
{
  pb::State s;
  s.position.assign(pb::MAX_JOINTS, 1.F);
  s.velocity.assign(pb::MAX_JOINTS, 2.F);
  s.has_imu = true;
  EXPECT_FALSE(pb::make_state(s).empty());
}

TEST(Protocol, ResyncAfterNoiseAndBadCrc)
{
  pb::Parser p;
  std::vector<uint8_t> bytes{0x00, 0xAA, 0x13, 0xAA};   // noise, a false start
  auto bad = pb::make_command({1.F});
  bad[6] ^= 0xFF;                                         // corrupt one payload byte
  bytes.insert(bytes.end(), bad.begin(), bad.end());
  const auto good = pb::make_command({2.F, 3.F});
  bytes.insert(bytes.end(), good.begin(), good.end());
  const auto frames = parse_all(bytes, p);
  ASSERT_EQ(frames.size(), 1u);
  std::vector<float> v;
  ASSERT_TRUE(pb::parse_command(frames[0], v));
  EXPECT_EQ(v, (std::vector<float>{2.F, 3.F}));
  EXPECT_GE(p.errors(), 1u);
}

TEST(Protocol, HelloAck)
{
  pb::Parser p;
  const auto frames = parse_all(pb::make_hello_ack(6, true, "arm6"), p);
  ASSERT_EQ(frames.size(), 1u);
  pb::Hello h;
  ASSERT_TRUE(pb::parse_hello_ack(frames[0], h));
  EXPECT_EQ(h.version, pb::VERSION);
  EXPECT_EQ(h.joints, 6);
  EXPECT_EQ(h.has_imu, 1);
  EXPECT_EQ(h.robot, "arm6");
}

TEST(Protocol, RejectsWrongSizes)
{
  pb::Frame f;
  f.type = pb::MsgType::COMMAND;
  f.payload = {3, 0, 0};   // says 3 floats, has 2 bytes
  std::vector<float> v;
  EXPECT_FALSE(pb::parse_command(f, v));
}

ros2lab_firmware.ros2lab_bridge/actuators.cpp:
// Quadrature encoders: an interrupt on every change of channel A, channel B gives the direction (2 counts per
// encoder line: counts_per_rev = encoder lines x 2 x gear ratio). Up to 6 encoders.
// On the Arduino Mega, channel A must be an interrupt pin: 2, 3, 18, 19, 20 or 21. On the ESP32 any input pin works.
#include "actuators.h"

namespace bridge
{

static volatile long counts[6];
static uint8_t pin_b[6];

#if defined(ARDUINO_ARCH_ESP32)
#define ISR_ATTR IRAM_ATTR
#else
#define ISR_ATTR
#endif

static void ISR_ATTR edge(uint8_t i, uint8_t a_pin)
{
  const bool a = digitalRead(a_pin), b = digitalRead(pin_b[i]);
  counts[i] += (a == b) ? -1 : 1;
}
static uint8_t pin_a[6];
static void ISR_ATTR isr0() { edge(0, pin_a[0]); }
static void ISR_ATTR isr1() { edge(1, pin_a[1]); }
static void ISR_ATTR isr2() { edge(2, pin_a[2]); }
static void ISR_ATTR isr3() { edge(3, pin_a[3]); }
static void ISR_ATTR isr4() { edge(4, pin_a[4]); }
static void ISR_ATTR isr5() { edge(5, pin_a[5]); }
static void (* const isrs[6])() = {isr0, isr1, isr2, isr3, isr4, isr5};

void encoder_attach(uint8_t idx, uint8_t a, uint8_t b)
{
  if (idx >= 6) return;
  pin_a[idx] = a; pin_b[idx] = b;
  pinMode(a, INPUT_PULLUP); pinMode(b, INPUT_PULLUP);
  attachInterrupt(digitalPinToInterrupt(a), isrs[idx], CHANGE);
}

long encoder_count(uint8_t idx)
{
  if (idx >= 6) return 0;
  noInterrupts();
  const long c = counts[idx];
  interrupts();
  return c;
}

}  // namespace bridge

ros2lab_firmware.ros2lab_bridge/actuators.h:
// Actuators of the ROS2Lab course robots, for the ESP32 (Arduino core 3.x) and the Arduino Mega 2560:
//   ServoPwm      a hobby servo (MG996R, DS3218, SG90) on a GPIO pin: position in rad, no feedback (the estimate ramps)
//   ServoPca9685  the same, on a PCA9685 16-channel PWM board (I2C 0x40) for robots with many servos (legs)
//   StsServo      a Feetech STS3215 serial bus servo (SO-101 style arms): position command and real position feedback
//   DcMotor       a DC gear motor with a quadrature encoder and a TB6612FNG / L298N / BTS7960 driver: velocity (rad/s)
//                 or position (rad) control with a PID loop
#pragma once
#include <Arduino.h>
#include <Wire.h>
#include "bridge_core.h"
#if defined(ARDUINO_ARCH_AVR)
#include <Servo.h>
#endif

namespace bridge
{

static inline float clampf(float v, float lo, float hi) { return v < lo ? lo : (v > hi ? hi : v); }

// ---------------- hobby servo ----------------
// us_min..us_max is the pulse range of the servo's whole travel (e.g. 500..2500 us for 180 deg on an MG996R, 270 deg on
// a DS3218); the middle of it is the servo's centre. zero_rad is the joint angle at the servo's centre (calibration:
// usually 0). Commands are clamped to the joint's limits rad_min..rad_max, never to the servo's travel.
struct ServoRange { uint16_t us_min, us_max; float travel_rad; float rad_min, rad_max; float max_speed; bool invert; float zero_rad; };

class ServoBase : public Actuator
{
public:
  explicit ServoBase(const ServoRange & r, float initial = 0) : r_(r), target_(initial), est_(initial) {}
  void enable(bool on) override { on_ = on; if (!on) detach(); else attach(); }
  void command(float v) override { target_ = clampf(v, r_.rad_min, r_.rad_max); }
  void update(float dt) override
  {
    // a hobby servo has no feedback: estimate where it is from its speed (rad/s at no load, from its data sheet)
    const float step = r_.max_speed * dt, d = target_ - est_;
    vel_ = d > step ? r_.max_speed : (d < -step ? -r_.max_speed : d / (dt > 0 ? dt : 1));
    est_ += d > step ? step : (d < -step ? -step : d);
    if (on_) write_us(us(target_));
  }
  float position() override { return est_; }
  float velocity() override { return vel_; }

protected:
  uint16_t us(float rad) const
  {
    float k = (rad - r_.zero_rad) / r_.travel_rad;    // -0.5 .. 0.5 over the servo's travel
    if (r_.invert) k = -k;
    return (uint16_t)(0.5f * (r_.us_min + r_.us_max) + clampf(k, -0.5f, 0.5f) * (r_.us_max - r_.us_min));
  }
  virtual void attach() {}
  virtual void detach() {}
  virtual void write_us(uint16_t us) = 0;
  ServoRange r_;
  float target_, est_, vel_ = 0;
  bool on_ = false;
};

class ServoPwm : public ServoBase
{
public:
  ServoPwm(uint8_t pin, const ServoRange & r, float initial = 0) : ServoBase(r, initial), pin_(pin) {}
  void begin() override {}

protected:
#if defined(ARDUINO_ARCH_ESP32)
  void attach() override { ledcAttach(pin_, 50, 16); }                 // 50 Hz, 16-bit duty
  void detach() override { ledcDetach(pin_); }
  void write_us(uint16_t us) override { ledcWrite(pin_, (uint32_t)us * 65535UL / 20000UL); }
#else
  void attach() override { if (!s_.attached()) s_.attach(pin_, r_.us_min, r_.us_max); }   // the library's default is 544..2400 us
  void detach() override { s_.detach(); }
  void write_us(uint16_t us) override { s_.writeMicroseconds(us); }
  Servo s_;
#endif
  uint8_t pin_;
};

// ---------------- PCA9685 (16 channels, I2C) ----------------
class Pca9685
{
public:
  explicit Pca9685(uint8_t addr = 0x40) : addr_(addr) {}
  void begin(TwoWire & wire = Wire)
  {
    w_ = &wire;
    write8(0x00, 0x10);                         // MODE1: sleep
    write8(0xFE, 121);                          // PRESCALE: 25 MHz / (4096 * 50 Hz) - 1 = 121
    write8(0x00, 0x20);                         // MODE1: wake, auto-increment
    delay(1);
    write8(0x00, 0xA0);                         // restart + auto-increment
  }
  void set_us(uint8_t ch, uint16_t us)          // 20 ms period: 4096 ticks
  {
    const uint16_t off = us ? (uint16_t)((uint32_t)us * 4096UL / 20000UL) : 0;
    w_->beginTransmission(addr_);
    w_->write(0x06 + 4 * ch);
    w_->write(0); w_->write(0);                 // ON at 0
    w_->write(off & 0xFF); w_->write(us ? (off >> 8) : 0x10);   // full OFF when us = 0 (servo relaxed)
    w_->endTransmission();
  }

private:
  void write8(uint8_t reg, uint8_t v) { w_->beginTransmission(addr_); w_->write(reg); w_->write(v); w_->endTransmission(); }
  uint8_t addr_;
  TwoWire * w_ = &Wire;
};

class ServoPca9685 : public ServoBase
{
public:
  ServoPca9685(Pca9685 & board, uint8_t channel, const ServoRange & r, float initial = 0) : ServoBase(r, initial), b_(board), ch_(channel) {}
  void begin() override {}

protected:
  void detach() override { b_.set_us(ch_, 0); }
  void write_us(uint16_t us) override { b_.set_us(ch_, us); }
  Pca9685 & b_;
  uint8_t ch_;
};

// ---------------- Feetech STS3215 serial bus servo (half duplex, 1 Mbps) ----------------
class StsBus
{
public:
  explicit StsBus(HardwareSerial & s) : s_(s) {}
  // the bus runs at 1 Mbit/s through a half-duplex adapter (Waveshare / Feetech bus-servo board, or a 74LS241 circuit)
#if defined(ARDUINO_ARCH_ESP32)
  void begin(int8_t rx_pin, int8_t tx_pin, uint32_t baud = 1000000) { s_.begin(baud, SERIAL_8N1, rx_pin, tx_pin); }
#else
  void begin(int8_t, int8_t, uint32_t baud = 1000000) { s_.begin(baud); }
#endif
  void write_pos(uint8_t id, int16_t pos, uint16_t speed)
  {
    const uint8_t p[] = {0x2A, (uint8_t)(pos & 0xFF), (uint8_t)(pos >> 8), 0, 0, (uint8_t)(speed & 0xFF), (uint8_t)(speed >> 8)};
    packet(id, 0x03, p, sizeof(p));             // WRITE goal position, time, speed
  }
  void torque(uint8_t id, bool on) { const uint8_t p[] = {0x28, (uint8_t)(on ? 1 : 0)}; packet(id, 0x03, p, 2); }
  bool read_pos(uint8_t id, int16_t & pos, int16_t & speed)
  {
    const uint8_t p[] = {0x38, 4};              // present position (2) + present speed (2)
    while (s_.available()) s_.read();
    packet(id, 0x02, p, 2);
    uint8_t r[10]; uint8_t n = 0; const uint32_t t0 = micros();
    while (n < 10 && micros() - t0 < 3000) if (s_.available()) r[n++] = (uint8_t)s_.read();
    if (n < 10 || r[0] != 0xFF || r[1] != 0xFF || r[2] != id) return false;
    pos = (int16_t)(r[5] | (r[6] << 8));
    uint16_t sp = (uint16_t)(r[7] | (r[8] << 8));
    speed = (sp & 0x8000) ? -(int16_t)(sp & 0x7FFF) : (int16_t)sp;   // bit 15 = direction
    return true;
  }

private:
  void packet(uint8_t id, uint8_t instr, const uint8_t * p, uint8_t n)
  {
    uint8_t sum = id + (n + 2) + instr;
    s_.write(0xFF); s_.write(0xFF); s_.write(id); s_.write((uint8_t)(n + 2)); s_.write(instr);
    for (uint8_t i = 0; i < n; ++i) { s_.write(p[i]); sum += p[i]; }
    s_.write((uint8_t)~sum);
    s_.flush();
  }
  HardwareSerial & s_;
};

class StsServo : public Actuator
{
public:
  // offset: the raw position (0..4095) that is 0 rad in the URDF; sign: +1 or -1
  StsServo(StsBus & bus, uint8_t id, int16_t offset = 2048, int8_t sign = 1, float lo = -3.0f, float hi = 3.0f)
  : bus_(bus), id_(id), off_(offset), sign_(sign), lo_(lo), hi_(hi) {}
  void begin() override {}
  void enable(bool on) override { bus_.torque(id_, on); on_ = on; }
  void command(float v) override { target_ = clampf(v, lo_, hi_); dirty_ = true; }
  void update(float) override
  {
    if (on_ && dirty_) { bus_.write_pos(id_, (int16_t)(off_ + sign_ * target_ * 4096.0f / 6.2831853f), 0); dirty_ = false; }
    if (++skip_ % 4 == 0) {                      // read back at a quarter of the loop rate (the bus is shared)
      int16_t p, s;
      if (bus_.read_pos(id_, p, s)) { pos_ = sign_ * (p - off_) * 6.2831853f / 4096.0f; vel_ = sign_ * s * 6.2831853f / 4096.0f; }
    }
  }
  float position() override { return pos_; }
  float velocity() override { return vel_; }

private:
  StsBus & bus_;
  uint8_t id_;
  int16_t off_;
  int8_t sign_;
  float lo_, hi_, target_ = 0, pos_ = 0, vel_ = 0;
  bool on_ = false, dirty_ = false;
  uint8_t skip_ = 0;
};

// ---------------- DC motor with encoder ----------------
enum class Driver : uint8_t { TB6612, L298N, BTS7960 };
struct MotorPins { Driver driver; uint8_t pwm_a, pin_b, pin_c, enc_a, enc_b; };   // TB6612/L298N: PWM, IN1, IN2; BTS7960: RPWM, LPWM, (unused)
struct MotorTuning { float counts_per_rev; float kp, ki, kd; float max_vel; bool position_mode; bool invert; };

void encoder_attach(uint8_t idx, uint8_t pin_a, uint8_t pin_b);   // actuators.cpp: interrupt trampolines
long encoder_count(uint8_t idx);

class DcMotor : public Actuator
{
public:
  DcMotor(uint8_t index, const MotorPins & p, const MotorTuning & t) : i_(index), p_(p), t_(t) {}
  void begin() override
  {
    pinMode(p_.pwm_a, OUTPUT); pinMode(p_.pin_b, OUTPUT);
    if (p_.driver != Driver::BTS7960) pinMode(p_.pin_c, OUTPUT);
#if defined(ARDUINO_ARCH_ESP32)
    ledcAttach(p_.pwm_a, 20000, 10);            // 20 kHz, 10-bit: quiet motors
    if (p_.driver == Driver::BTS7960) ledcAttach(p_.pin_b, 20000, 10);
#endif
    encoder_attach(i_, p_.enc_a, p_.enc_b);
    last_ = encoder_count(i_);
    drive(0);
  }
  void enable(bool on) override { on_ = on; integ_ = 0; if (!on) drive(0); }
  void command(float v) override { target_ = t_.position_mode ? v : clampf(v, -t_.max_vel, t_.max_vel); }
  void update(float dt) override
  {
    if (dt <= 0) return;
    const long c = encoder_count(i_);
    const float k = (t_.invert ? -1.0f : 1.0f) * 6.2831853f / t_.counts_per_rev;
    pos_ = c * k;
    const float v_now = (c - last_) * k / dt;
    vel_ = 0.7f * vel_ + 0.3f * v_now;            // a light low-pass on the measured speed
    last_ = c;
    if (!on_) return;
    const float want = t_.position_mode ? clampf(2.5f * (target_ - pos_), -t_.max_vel, t_.max_vel) : target_;
    const float e = want - vel_;
    integ_ = clampf(integ_ + e * dt, -1.0f, 1.0f);
    const float de = (e - prev_e_) / dt; prev_e_ = e;
    float u = t_.kp * e + t_.ki * integ_ + t_.kd * de + want / t_.max_vel;   // feed-forward + PID
    if (!t_.position_mode && fabsf(target_) < 1e-3f && fabsf(vel_) < 0.05f) { u = 0; integ_ = 0; }
    drive(clampf(u, -1, 1) * (t_.invert ? -1 : 1));
  }
  float position() override { return pos_; }
  float velocity() override { return vel_; }

private:
  void pwm(uint8_t pin, uint16_t duty)
  {
#if defined(ARDUINO_ARCH_ESP32)
    ledcWrite(pin, duty);                        // 0..1023
#else
    analogWrite(pin, duty >> 2);                 // 0..255
#endif
  }
  void drive(float u)                            // -1 .. 1
  {
    const uint16_t d = (uint16_t)(fabsf(u) * 1023);
    if (p_.driver == Driver::BTS7960) { pwm(p_.pwm_a, u > 0 ? d : 0); pwm(p_.pin_b, u < 0 ? d : 0); return; }
    digitalWrite(p_.pin_b, u > 0 ? HIGH : LOW);
    digitalWrite(p_.pin_c, u < 0 ? HIGH : LOW);
    pwm(p_.pwm_a, d);
  }
  uint8_t i_;
  MotorPins p_;
  MotorTuning t_;
  float target_ = 0, pos_ = 0, vel_ = 0, integ_ = 0, prev_e_ = 0;
  long last_ = 0;
  bool on_ = false;
};

}  // namespace bridge

ros2lab_firmware.ros2lab_bridge/bridge_core.h:
// The board's logic, independent of the hardware: answers HELLO, applies COMMANDs to the actuators, reports STATE,
// enables / disables the motors and stops everything when the Jetson goes quiet (watchdog). Hardware lives behind the
// Actuator and Imu interfaces (actuators.h, imu.h), so the same core runs on an ESP32, an Arduino Mega and in the
// host tests (firmware/test).
#pragma once
#include "bridge_proto.h"

namespace bridge
{

class Actuator
{
public:
  virtual ~Actuator() {}
  virtual void begin() = 0;
  virtual void enable(bool on) = 0;
  virtual void command(float value) = 0;   // position (rad or m) or velocity (rad/s), as the joint is configured
  virtual void update(float dt) = 0;       // the control loop (PID, ramps), called every few milliseconds
  virtual float position() = 0;
  virtual float velocity() = 0;
};

class Imu
{
public:
  virtual ~Imu() {}
  virtual bool begin() = 0;
  // orientation quaternion x y z w, angular velocity rad/s, linear acceleration m/s^2 (gravity included, as sensor_msgs/Imu)
  virtual bool read(float q[4], float gyro[3], float accel[3]) = 0;
};

class Link
{
public:
  virtual ~Link() {}
  virtual void send(const uint8_t * data, uint16_t n) = 0;
};

class Core
{
public:
  Core(Actuator ** acts, uint8_t n, const char * robot_id, Imu * imu = 0)
  : a_(acts), n_(n), id_(robot_id), imu_(imu) {}

  void begin()
  {
    for (uint8_t i = 0; i < n_; ++i) a_[i]->begin();
    imu_ok_ = imu_ && imu_->begin();
  }

  // one complete frame from a link (USB serial or UDP); the answer goes back on the same link
  void handle(const Parser & p, uint32_t now_ms, Link & link)
  {
    switch (p.type()) {
      case T_HELLO: {
        FrameWriter w(out_, T_HELLO_ACK);
        w.u8(VERSION); w.u8(n_); w.u8(imu_ok_ ? 1 : 0); w.str(id_);
        link.send(out_, w.finish());
        break;
      }
      case T_PING: { FrameWriter w(out_, T_PONG); link.send(out_, w.finish()); break; }
      case T_ENABLE:
        enabled_ = p.length() >= 1 && p.payload()[0] == 1;
        for (uint8_t i = 0; i < n_; ++i) a_[i]->enable(enabled_);
        last_cmd_ = now_ms; watchdog_tripped_ = false;
        break;
      case T_COMMAND: {
        const uint8_t k = p.length() ? p.payload()[0] : 0;
        if (k == n_ && p.length() == 1 + 4 * k) {
          if (enabled_) for (uint8_t i = 0; i < n_; ++i) a_[i]->command(Parser::f32(p.payload() + 1 + 4 * i));
          last_cmd_ = now_ms;
          if (watchdog_tripped_ && enabled_) { watchdog_tripped_ = false; for (uint8_t i = 0; i < n_; ++i) a_[i]->enable(true); }
        } else if (k != 0) {   // an empty COMMAND only asks for the state
          fault(link, F_BAD_COMMAND, "COMMAND has the wrong number of joints");
        }
        send_state(now_ms, link);
        break;
      }
      default: break;
    }
  }

  // the control loop: actuators and the watchdog (call every 2 to 10 ms)
  void tick(uint32_t now_ms, float dt, Link * fault_link = 0)
  {
    if (enabled_ && !watchdog_tripped_ && now_ms - last_cmd_ > WATCHDOG_MS) {
      watchdog_tripped_ = true;
      for (uint8_t i = 0; i < n_; ++i) a_[i]->enable(false);
      if (fault_link) fault(*fault_link, F_WATCHDOG, "no command for 500 ms: motors stopped");
    }
    for (uint8_t i = 0; i < n_; ++i) a_[i]->update(dt);
  }

  bool enabled() const { return enabled_ && !watchdog_tripped_; }
  uint8_t joints() const { return n_; }

private:
  void send_state(uint32_t now_ms, Link & link)
  {
    FrameWriter w(out_, T_STATE);
    w.u32(now_ms); w.u8(n_);
    for (uint8_t i = 0; i < n_; ++i) { w.f32(a_[i]->position()); w.f32(a_[i]->velocity()); }
    float q[4] = {0, 0, 0, 1}, g[3] = {0, 0, 0}, ac[3] = {0, 0, 0};
    const bool imu = imu_ok_ && imu_->read(q, g, ac);
    w.u8(imu ? 1 : 0);
    if (imu) { for (uint8_t i = 0; i < 4; ++i) w.f32(q[i]); for (uint8_t i = 0; i < 3; ++i) w.f32(g[i]); for (uint8_t i = 0; i < 3; ++i) w.f32(ac[i]); }
    link.send(out_, w.finish());
  }
  void fault(Link & link, FaultCode c, const char * text)
  {
    FrameWriter w(out_, T_FAULT);
    w.u8(c); w.str(text);
    link.send(out_, w.finish());
  }

  Actuator ** a_;
  uint8_t n_;
  const char * id_;
  Imu * imu_;
  bool imu_ok_ = false, enabled_ = false, watchdog_tripped_ = false;
  uint32_t last_cmd_ = 0;
  uint8_t out_[MAX_PAYLOAD + 8];
};

}  // namespace bridge

ros2lab_firmware.ros2lab_bridge/bridge_proto.h:
// ROS2Lab bridge protocol, microcontroller side: the same frames as ros2lab_hardware/protocol.hpp (the Jetson side),
// written without the C++ standard library so that it also fits an Arduino Mega (AVR). A host test
// (firmware/test/test_interop.cpp) checks that both sides produce and read identical bytes.
//   frame: 0xAA 0x55 | type | length | payload | CRC-16/CCITT-FALSE (little endian), CRC over type, length, payload
#pragma once
#include <stdint.h>
#include <string.h>

namespace bridge
{

static const uint8_t SYNC0 = 0xAA, SYNC1 = 0x55, VERSION = 1;
static const uint8_t MAX_PAYLOAD = 240, MAX_JOINTS = 24;
static const uint32_t WATCHDOG_MS = 500;
// (T_ prefix: AVR headers already define PING, a port register)
enum Type : uint8_t { T_HELLO = 0x01, T_COMMAND = 0x02, T_ENABLE = 0x03, T_PING = 0x04, T_HELLO_ACK = 0x81, T_STATE = 0x82, T_PONG = 0x84, T_FAULT = 0x85 };
enum FaultCode : uint8_t { F_NONE = 0, F_WATCHDOG = 1, F_BAD_COMMAND = 2, F_OVERCURRENT = 3, F_IMU = 4, F_LOW_BATTERY = 5 };

inline uint16_t crc16(const uint8_t * d, uint16_t n, uint16_t crc = 0xFFFF)
{
  for (uint16_t i = 0; i < n; ++i) {
    crc ^= (uint16_t)d[i] << 8;
    for (uint8_t b = 0; b < 8; ++b) crc = (crc & 0x8000) ? (uint16_t)((crc << 1) ^ 0x1021) : (uint16_t)(crc << 1);
  }
  return crc;
}

// builds one frame in a caller-owned buffer (at least MAX_PAYLOAD + 6 bytes)
class FrameWriter
{
public:
  FrameWriter(uint8_t * buf, Type t) : b_(buf), n_(4) { b_[0] = SYNC0; b_[1] = SYNC1; b_[2] = t; }
  void u8(uint8_t v) { if (n_ < MAX_PAYLOAD + 4) b_[n_++] = v; }
  void u32(uint32_t v) { for (uint8_t i = 0; i < 4; ++i) u8((uint8_t)(v >> (8 * i))); }
  void f32(float v) { uint32_t u; memcpy(&u, &v, 4); u32(u); }
  void str(const char * s) { while (*s) u8((uint8_t)*s++); }
  // finishes the frame: returns its total length
  uint16_t finish()
  {
    b_[3] = (uint8_t)(n_ - 4);
    const uint16_t c = crc16(b_ + 2, (uint16_t)(n_ - 2));
    b_[n_++] = (uint8_t)(c & 0xFF);
    b_[n_++] = (uint8_t)(c >> 8);
    return n_;
  }

private:
  uint8_t * b_;
  uint16_t n_;
};

// reads frames byte by byte, resynchronising after noise or a bad CRC
class Parser
{
public:
  // true when a complete frame is ready: type(), length(), payload()
  bool push(uint8_t c)
  {
    switch (st_) {
      case 0: if (c == SYNC0) st_ = 1; return false;
      case 1: st_ = c == SYNC1 ? 2 : (c == SYNC0 ? 1 : 0); return false;
      case 2: type_ = c; st_ = 3; return false;
      case 3: len_ = c; i_ = 0; if (len_ > MAX_PAYLOAD) { st_ = 0; ++errors_; return false; } st_ = len_ ? 4 : 5; return false;
      case 4: pl_[i_++] = c; if (i_ == len_) st_ = 5; return false;
      case 5: lo_ = c; st_ = 6; return false;
      case 6: {
        st_ = 0;
        uint16_t crc = crc16(&type_, 1);
        crc = crc16(&len_, 1, crc);
        crc = crc16(pl_, len_, crc);
        if (crc != (uint16_t)(lo_ | (c << 8))) { ++errors_; return false; }
        return true;
      }
    }
    st_ = 0;
    return false;
  }
  uint8_t type() const { return type_; }
  uint8_t length() const { return len_; }
  const uint8_t * payload() const { return pl_; }
  uint16_t errors() const { return errors_; }
  static float f32(const uint8_t * p) { uint32_t u = (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) | ((uint32_t)p[3] << 24); float v; memcpy(&v, &u, 4); return v; }

private:
  uint8_t st_ = 0, type_ = 0, len_ = 0, i_ = 0, lo_ = 0;
  uint8_t pl_[MAX_PAYLOAD];
  uint16_t errors_ = 0;
};

}  // namespace bridge

ros2lab_firmware.ros2lab_bridge/imu.h:
// IMUs on I2C, without extra libraries:
//   Mpu6050  (GY-521 board, 0x68): gyro + accelerometer; orientation from a complementary filter (yaw drifts slowly)
//   Bno055   (0x28): Bosch's own 9-axis fusion (NDOF): absolute orientation
// Output follows sensor_msgs/Imu: quaternion x y z w, angular velocity rad/s, linear acceleration m/s^2 (with gravity).
#pragma once
#include <Arduino.h>
#include <Wire.h>
#include <math.h>
#include "bridge_core.h"

namespace bridge
{

class I2cDev
{
protected:
  explicit I2cDev(uint8_t addr) : addr_(addr) {}
  bool write8(uint8_t reg, uint8_t v) { Wire.beginTransmission(addr_); Wire.write(reg); Wire.write(v); return Wire.endTransmission() == 0; }
  bool read(uint8_t reg, uint8_t * buf, uint8_t n)
  {
    Wire.beginTransmission(addr_); Wire.write(reg);
    if (Wire.endTransmission(false) != 0) return false;
    if (Wire.requestFrom(addr_, n) != n) return false;
    for (uint8_t i = 0; i < n; ++i) buf[i] = (uint8_t)Wire.read();
    return true;
  }
  uint8_t addr_;
};

class Mpu6050 : public Imu, I2cDev
{
public:
  explicit Mpu6050(uint8_t addr = 0x68) : I2cDev(addr) {}
  bool begin() override
  {
    if (!write8(0x6B, 0x01)) return false;     // PWR_MGMT_1: wake, PLL with X gyro
    write8(0x1A, 0x03);                        // CONFIG: 44 Hz low-pass
    write8(0x1B, 0x08);                        // GYRO_CONFIG: +-500 deg/s (65.5 LSB per deg/s)
    write8(0x1C, 0x08);                        // ACCEL_CONFIG: +-4 g (8192 LSB per g)
    last_ = micros();
    return true;
  }
  bool read(float q[4], float g[3], float a[3]) override
  {
    uint8_t b[14];
    if (!I2cDev::read(0x3B, b, 14)) return false;
    const float ax = (int16_t)(b[0] << 8 | b[1]) / 8192.0f * 9.80665f, ay = (int16_t)(b[2] << 8 | b[3]) / 8192.0f * 9.80665f, az = (int16_t)(b[4] << 8 | b[5]) / 8192.0f * 9.80665f;
    const float d2r = 0.0174532925f / 65.5f;
    const float gx = (int16_t)(b[8] << 8 | b[9]) * d2r, gy = (int16_t)(b[10] << 8 | b[11]) * d2r, gz = (int16_t)(b[12] << 8 | b[13]) * d2r;
    const uint32_t now = micros(); const float dt = (now - last_) * 1e-6f; last_ = now;
    // complementary filter: gyro short term, gravity direction long term
    roll_ = 0.98f * (roll_ + gx * dt) + 0.02f * atan2f(ay, az);
    pitch_ = 0.98f * (pitch_ + gy * dt) + 0.02f * atan2f(-ax, sqrtf(ay * ay + az * az));
    yaw_ += gz * dt;
    const float cr = cosf(roll_ / 2), sr = sinf(roll_ / 2), cp = cosf(pitch_ / 2), sp = sinf(pitch_ / 2), cy = cosf(yaw_ / 2), sy = sinf(yaw_ / 2);
    q[0] = sr * cp * cy - cr * sp * sy; q[1] = cr * sp * cy + sr * cp * sy; q[2] = cr * cp * sy - sr * sp * cy; q[3] = cr * cp * cy + sr * sp * sy;
    g[0] = gx; g[1] = gy; g[2] = gz; a[0] = ax; a[1] = ay; a[2] = az;
    return true;
  }

private:
  uint32_t last_ = 0;
  float roll_ = 0, pitch_ = 0, yaw_ = 0;
};

class Bno055 : public Imu, I2cDev
{
public:
  explicit Bno055(uint8_t addr = 0x28) : I2cDev(addr) {}
  bool begin() override
  {
    uint8_t id = 0;
    if (!I2cDev::read(0x00, &id, 1) || id != 0xA0) return false;   // CHIP_ID
    write8(0x3D, 0x00); delay(25);                                 // CONFIG mode
    write8(0x3B, 0x06);                                            // UNIT_SEL: m/s^2, rad/s, radians
    write8(0x3D, 0x0C); delay(20);                                 // NDOF fusion mode
    return true;
  }
  bool read(float q[4], float g[3], float a[3]) override
  {
    uint8_t b[8], gb[6], ab[6];
    if (!I2cDev::read(0x20, b, 8) || !I2cDev::read(0x14, gb, 6) || !I2cDev::read(0x08, ab, 6)) return false;
    const float s = 1.0f / 16384.0f;
    q[3] = (int16_t)(b[1] << 8 | b[0]) * s; q[0] = (int16_t)(b[3] << 8 | b[2]) * s; q[1] = (int16_t)(b[5] << 8 | b[4]) * s; q[2] = (int16_t)(b[7] << 8 | b[6]) * s;
    for (uint8_t i = 0; i < 3; ++i) { g[i] = (int16_t)(gb[2 * i + 1] << 8 | gb[2 * i]) / 900.0f; a[i] = (int16_t)(ab[2 * i + 1] << 8 | ab[2 * i]) / 100.0f; }
    return true;
  }
};

}  // namespace bridge

ros2lab_firmware.ros2lab_bridge/ros2lab_bridge.ino:
// ROS2Lab bridge firmware: the microcontroller between the Jetson (ROS 2 Jazzy, ros2_control) and the robot's
// servos, motors, encoders and IMU. Works on:
//   ESP32 (DevKitC, ESP32-S3)  USB serial and/or Wi-Fi (UDP port 8888)   Arduino IDE: board "ESP32 Dev Module", core 3.x
//   Arduino Mega 2560          USB serial                                Arduino IDE: board "Arduino Mega or Mega 2560"
// The robot (which joints, which pins) is in robot_config.h: generate it for your robot with
//   ros2 run ros2lab_hardware ros2lab_robot_setup <robot>_description --type <arm|diff|mecanum|ackermann|legged|...>
// The Jetson side is the ros2lab_hardware/BridgeSystem plugin; the protocol is in bridge_proto.h.
// Safety: the motors only move after the Jetson sends ENABLE, and they stop 500 ms after the last command.
#include <Arduino.h>
#include <Wire.h>
#include "bridge_core.h"
#include "actuators.h"
#include "imu.h"
#include "robot_config.h"   // ROBOT_ID, BRIDGE_BAUD, robot_setup(), optional WIFI_SSID / WIFI_PASS / WIFI_AP
#ifdef WIFI_PASS   // refuse to build with the example's default password (ros2lab_robot_setup makes a random one)
constexpr bool r2l_streq(const char* a, const char* b) { return *a == *b && (*a == '\0' || r2l_streq(a + 1, b + 1)); }
static_assert(!r2l_streq(WIFI_PASS, "change-this-password"), "Set your own WIFI_PASS in robot_config.h (ros2lab_robot_setup generates a random one)");
static_assert(sizeof(WIFI_PASS) > 8, "WIFI_PASS needs at least 8 characters (WPA2)");
#endif

#if defined(ARDUINO_ARCH_ESP32) && defined(WIFI_SSID)
#include <WiFi.h>
#include <WiFiUdp.h>
#define BRIDGE_WIFI 1
#endif
#ifndef UDP_PORT
#define UDP_PORT 8888
#endif
#ifndef CONTROL_PERIOD_US
#define CONTROL_PERIOD_US 5000   // 200 Hz control loop (PID, servo ramps)
#endif

static bridge::Actuator * actuators[bridge::MAX_JOINTS];
static uint8_t n_actuators = 0;
static bridge::Imu * imu = 0;
static bridge::Core * core = 0;

class SerialLink : public bridge::Link
{
public:
  void send(const uint8_t * d, uint16_t n) override { Serial.write(d, n); }
};
static SerialLink serial_link;
static bridge::Parser serial_parser;

#ifdef BRIDGE_WIFI
static WiFiUDP udp;
class UdpLink : public bridge::Link
{
public:
  void send(const uint8_t * d, uint16_t n) override { if (!peer_set) return; udp.beginPacket(peer, peer_port); udp.write(d, n); udp.endPacket(); }
  IPAddress peer;
  uint16_t peer_port = 0;
  bool peer_set = false;
  uint32_t last_rx = 0;
};
#ifndef PEER_LOCK_MS
#define PEER_LOCK_MS 2000   // while the Jetson talks, packets from any other address are ignored
#endif
static UdpLink udp_link;
static bridge::Parser udp_parser;
#endif

static bridge::Link * last_link = &serial_link;   // faults go to whoever talked last

void setup()
{
  Serial.begin(BRIDGE_BAUD);
  Wire.begin();
  Wire.setClock(400000);
  robot_setup(actuators, n_actuators, imu);
  static bridge::Core c(actuators, n_actuators, ROBOT_ID, imu);
  core = &c;
  core->begin();
#ifdef BRIDGE_WIFI
#ifdef WIFI_AP
  WiFi.softAP(WIFI_SSID, WIFI_PASS);           // the robot makes its own network: the Jetson joins it (ESP32 is 192.168.4.1)
#else
  WiFi.mode(WIFI_STA);
  WiFi.begin(WIFI_SSID, WIFI_PASS);            // the robot joins the lab network: give it a fixed address in the router
  for (uint8_t i = 0; i < 40 && WiFi.status() != WL_CONNECTED; ++i) delay(250);
#endif
  WiFi.setSleep(false);                        // no power save: steady latency
  udp.begin(UDP_PORT);
#endif
}

void loop()
{
  const uint32_t now = millis();
  while (Serial.available()) {
    if (serial_parser.push((uint8_t)Serial.read())) { last_link = &serial_link; core->handle(serial_parser, now, serial_link); }
  }
#ifdef BRIDGE_WIFI
  int size = udp.parsePacket();
  if (size > 0) {
    uint8_t buf[256];
    const int n = udp.read(buf, sizeof(buf));
    const bool same = udp_link.peer_set && udp.remoteIP() == udp_link.peer && udp.remotePort() == udp_link.peer_port;
    if (!same && udp_link.peer_set && now - udp_link.last_rx < PEER_LOCK_MS) return;   // another computer while the Jetson is connected
    if (!same) { udp_link.peer = udp.remoteIP(); udp_link.peer_port = udp.remotePort(); udp_link.peer_set = true; udp_parser = bridge::Parser(); }
    udp_link.last_rx = now;
    for (int i = 0; i < n; ++i) if (udp_parser.push(buf[i])) { last_link = &udp_link; core->handle(udp_parser, now, udp_link); }
  }
#endif
  static uint32_t last_us = micros();
  const uint32_t t = micros();
  if (t - last_us >= CONTROL_PERIOD_US) {
    core->tick(now, (t - last_us) * 1e-6f, last_link);
    last_us = t;
  }
}
